const fields=['pins','ledger','handoffs'] as const;
const refSchema=z.object({sha256:z.string().regex(/^[a-f0-9]{64}$/),byteLength:z.number().int().positive().max(65536)}).strict();
type Ref=z.infer<typeof refSchema>;
const descriptor=z.object({bucket:z.number().int().min(0).max(15),count:z.number().int().positive().max(16),ref:refSchema}).strict();
