const page=z.object({schema:z.literal('cgp.page.v0'),field:z.enum(fields),bucket:z.number().int().min(0).max(15),rows:z.array(z.object({ordinal:z.number().int().min(0).max(63),row:z.unknown()}).strict()).min(1).max(16)}).strict();
