function check(v:unknown,reason='cgp_integrity_invalid'):asserts v {if(!v)throw Error(reason);}
const same=(a:unknown,b:unknown)=>canonicalOwnedJson(a)===canonicalOwnedJson(b);
export const cgpState=(v:unknown)=>{const s=registryStateSchema.parse(v);return {...s,handoffs:s.handoffs??[]};};
function key(field:typeof fields[number],v:any){const k=field==='pins'?v?.ref?.id:field==='ledger'?v?.key:v?.operationKey;check(typeof k==='string'&&k.length>0,'cgp_key_invalid');return k as string;}
